const body = $input.item.json.body || $input.item.json;
const locationId = body.locationId;
const contactId = body.contactId;

if (!contactId || !locationId) {
  throw new Error('Falta contactId o locationId en el payload del webhook de GHL. Body recibido: ' + JSON.stringify(body));
}

// Location IDs y tokens de GHL (verificar contra el vault Carwarriors LLC.md si cambian)
const LOCATIONS = {
  'DSe5PdPEScZL8cbZTkKI': { dealer: 'CW', vendorName: 'Carwarriors LLC', token: 'pit-20fb00b2-9c40-4e3e-a3cb-4d38736bcbb3' },
  '1j1dHo8HEbZdElQUGFoC': { dealer: 'RANCES', vendorName: 'Rances Car', token: 'pit-c30b22ca-d09c-45a4-967e-8b75e574a783' }
};

const loc = LOCATIONS[locationId];
if (!loc) {
  throw new Error('Location de GHL desconocida (no es Carwarriors LLC ni Rances Car): ' + locationId);
}

return [{
  json: {
    contactId,
    locationId,
    dealer: loc.dealer,
    vendorName: loc.vendorName,
    ghlToken: loc.token
  }
}];

const contact = $json.contact;
const dealerInfo = $('Select Dealer + Token').item.json;
const dealer = dealerInfo.dealer;
const vendorName = dealerInfo.vendorName;

const attribution = contact.attributionSource || {};
const campaign = (attribution.campaign || '').toUpperCase();

let leadSource;
if (campaign.includes('TESLA')) {
  leadSource = `TESLA ${dealer}`;
} else if (campaign.includes('TRADE')) {
  leadSource = `TRADE IN ${dealer}`;
} else {
  leadSource = `META ${dealer}`;
}

const fullName = [contact.firstName, contact.lastName].filter(Boolean).join(' ') || 'Sin Nombre';
const email = contact.email || '';
const phone = contact.phone || '';

const customFields = contact.customFields || [];
const vehicleInterestField = customFields.find(f => f.id === 'HeQZLqZ0JXldicPk1AOJ');
const vehicleInterest = vehicleInterestField ? vehicleInterestField.value : '';

// requestdate ISO 8601 sin milisegundos ni zona horaria (formato validado en la prueba 2026-07-22)
const now = new Date().toISOString().replace(/\.\d{3}Z$/, '');

const escapeXml = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&apos;');

const vehicleBlock = vehicleInterest
  ? `<vehicle status="used" interest="buy"><make>${escapeXml(vehicleInterest)}</make></vehicle>`
  : `<vehicle status="used" interest="buy"><make>N/A</make></vehicle>`;

const xml = `<?xml version="1.0"?>
<?adf version="1.0"?>
<adf>
  <prospect>
    <id sequence="1" source="ghl-contact-id">${escapeXml(contact.id)}</id>
    <requestdate>${now}</requestdate>
    <requesttype>sales</requesttype>
    ${vehicleBlock}
    <customer>
      <contact>
        <name part="full">${escapeXml(fullName)}</name>
        ${email ? `<email>${escapeXml(email)}</email>` : ''}
        ${phone ? `<phone type="voice">${escapeXml(phone)}</phone>` : ''}
      </contact>
    </customer>
    <vendor>
      <id sequence="1" source="dealerId">14031841</id>
      <vendorname>${escapeXml(vendorName)}</vendorname>
    </vendor>
    <provider>
      <id sequence="1" source="sourcename">GoHighLevel</id>
      <name part="full">${escapeXml(leadSource)}</name>
    </provider>
  </prospect>
</adf>`;

const fileName = `${Date.now()}_${contact.id}.xml`;

return [{
  json: { leadSource, fileName, dealer },
  binary: {
    data: {
      data: Buffer.from(xml).toString('base64'),
      mimeType: 'application/xml',
      fileName
    }
  }
}];
